content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --border-color: #cbd5e1;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100dvh;
  max-width: 1000px;
  max-height: 800px;
  background-color: var(--card-bg);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border-color);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  background-color: #ffffff;
  border-bottom: 1px solid var(--border-color);
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-color);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  padding: 0.75rem 1.5rem;
  background-color: #f1f5f9;
  border-bottom: 1px solid var(--border-color);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.color-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  cursor: pointer;
  box-shadow: 0 0 0 1px var(--border-color);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}

.color-btn:hover {
  transform: scale(1.1);
}

.color-btn.active {
  box-shadow: 0 0 0 3px var(--primary-color);
  transform: scale(1.1);
}

.size-slider {
  appearance: none;
  width: 100px;
  height: 6px;
  border-radius: 3px;
  background: var(--border-color);
  outline: none;
}

.size-slider::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  transition: background 0.1s ease;
}

.size-slider::-webkit-slider-thumb:hover {
  background: var(--primary-hover);
}

.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: #ffffff;
  background-color: #64748b;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.action-btn:hover {
  background-color: #475569;
}

.action-btn.active {
  background-color: var(--primary-hover) !important;
}

.action-btn:active {
  transform: translateY(1px);
}

.canvas-container {
  flex: 1;
  position: relative;
  overflow: hidden;
  background-color: #ffffff;
  display: flex;
  justify-content: center;
  align-items: center;
  touch-action: none;
}

.drawing-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

@media (max-width: 640px) {
  .app-container {
    height: 100dvh;
    max-height: none;
    border-radius: 0;
    border: none;
  }

  .toolbar {
    padding: 0.5rem 1rem;
    gap: 0.5rem;
  }
}

import { useState, useRef, useEffect } from 'react';
import { Trash2, Palette, Sliders, Download, Undo2 } from 'lucide-react';

const COLORS = ['#1e293b', '#ef4444', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ffffff'];

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentColor, setCurrentColor] = useState('#1e293b');
  const [brushSize, setBrushSize] = useState(5);
  const [isEraser, setIsEraser] = useState(false);
  const [history, setHistory] = useState<ImageData[]>([]);

  const saveHistory = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    setHistory((prev) => [...prev, imageData]);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const width = parent.clientWidth;
      const height = parent.clientHeight;

      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvas.width;
      tempCanvas.height = canvas.height;
      const tempCtx = tempCanvas.getContext('2d');
      if (tempCtx) {
        tempCtx.drawImage(canvas, 0, 0);
      }

      canvas.width = width;
      canvas.height = height;

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, width, height);

      if (tempCanvas.width > 0 && tempCanvas.height > 0) {
        ctx.drawImage(tempCanvas, 0, 0);
      }
    };

    resizeCanvas();
    saveHistory();
    window.addEventListener('resize', resizeCanvas);
    return () => window.removeEventListener('resize', resizeCanvas);
  }, []);

  const startDrawing = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    let clientX = 0;
    let clientY = 0;

    if ('touches' in e) {
      if (e.touches.length === 0) return;
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }

    setIsDrawing(true);
    saveHistory();
    ctx.beginPath();
    ctx.moveTo(clientX - rect.left, clientY - rect.top);
  };

  const draw = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    let clientX = 0;
    let clientY = 0;

    if ('touches' in e) {
      if (e.touches.length === 0) return;
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }

    ctx.strokeStyle = isEraser ? '#ffffff' : currentColor;
    ctx.lineWidth = brushSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.lineTo(clientX - rect.left, clientY - rect.top);
    ctx.stroke();
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.closePath();
    }
  };

  const undo = () => {
    if (history.length === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const newHistory = [...history];
    const previousState = newHistory.pop();
    setHistory(newHistory);

    if (previousState) {
      ctx.putImageData(previousState, 0, 0);
    } else {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
  };

  const clearCanvas = () => {
    if (!window.confirm('本当にすべて消去しますか？')) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    saveHistory();
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  };

  const downloadCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = 'drawing.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">お絵かきボード</h1>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          <button className="action-btn" onClick={undo} disabled={history.length === 0} style={{ backgroundColor: '#64748b' }}>
            <Undo2 size={16} style={{ marginRight: '4px' }} />
            元に戻す
          </button>
          <button className="action-btn" onClick={downloadCanvas} style={{ backgroundColor: '#10b981' }}>
            <Download size={16} style={{ marginRight: '4px' }} />
            保存
          </button>
          <button className="action-btn" onClick={clearCanvas}>
            <Trash2 size={16} style={{ marginRight: '4px' }} />
            全消去
          </button>
        </div>
      </header>

      <div className="toolbar">
        <div className="tool-group">
          <Palette size={18} style={{ color: 'var(--text-color)' }} />
          {COLORS.map((color) => (
            <button
              key={color}
              className={`color-btn ${currentColor === color && !isEraser ? 'active' : ''}`}
              style={{ backgroundColor: color }}
              onClick={() => {
                setCurrentColor(color);
                setIsEraser(false);
              }}
              title={color}
            />
          ))}
        </div>

        <div className="tool-group">
          <Sliders size={18} style={{ color: 'var(--text-color)' }} />
          <input
            type="range"
            min="1"
            max="50"
            value={brushSize}
            onChange={(e) => setBrushSize(Number(e.target.value))}
            className="size-slider"
            title="太さ"
          />
          <span style={{ fontSize: '0.875rem', minWidth: '24px' }}>{brushSize}px</span>
        </div>

        <div className="tool-group">
          <button
            className={`action-btn ${isEraser ? 'active' : ''}`}
            style={{ backgroundColor: isEraser ? '#2563eb' : '#64748b' }}
            onClick={() => setIsEraser(!isEraser)}
          >
            消しゴム
          </button>
        </div>
      </div>

      <div className="canvas-container">
        <canvas
          ref={canvasRef}
          className="drawing-canvas"
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />
      </div>
    </div>
  );
}
